:host { display:block; color:#30343a; font:14px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans",Arial,sans-serif; }
* { box-sizing:border-box; }
.tm-shell { border:1px solid #e2e5e8; border-radius:12px; overflow:hidden; background:#fff; }
.tm-toolbar,.tm-tools,.tm-breadcrumb,.tm-replay { display:flex; align-items:center; flex-wrap:wrap; gap:7px; }
.tm-toolbar { justify-content:space-between; padding:12px 14px; border-bottom:1px solid #e2e5e8; }
button,select { color:inherit; background:#fff; border:1px solid #dde2dc; border-radius:6px; padding:7px 10px; cursor:pointer; font:inherit; }
button:hover,select:hover { background:#f2f5f0; border-color:#879d7f; }
button:disabled { opacity:.4; cursor:default; }
button:focus-visible,select:focus-visible,[tabindex]:focus-visible,input:focus-visible { outline:2px solid #69815e; outline-offset:3px; }
select { max-width:min(100%,420px); }
.tm-scale { min-width:42px; color:#71767e; text-align:center; font-variant-numeric:tabular-nums; }
.tm-breadcrumb { padding:9px 14px; min-height:48px; border-bottom:1px solid #e2e5e8; }
.tm-breadcrumb button { border:0; padding:3px 0; background:transparent; }
.tm-breadcrumb [aria-current] { font-weight:500; }
.tm-breadcrumb[hidden],.tm-status[hidden] { display:none; }
.canvas .tm-repeated-title { visibility:hidden; }
.tm-body { display:flex; min-width:0; }
.tm-viewport { flex:1; position:relative; min-width:0; height:600px; overflow:hidden; background:#fff; touch-action:pan-y pinch-zoom; cursor:grab; }
.tm-viewport.is-dragging { cursor:grabbing; user-select:none; }
.tm-world { position:absolute; transform-origin:0 0; }
.diagram-root,.canvas { background:transparent; }
.canvas { overflow:visible; }
.canvas .node,.canvas .bundle,.canvas .checkpoint,.canvas .restore { border-radius:8px; box-shadow:none; }
.canvas [role="button"] { cursor:pointer; transition:opacity .15s,border-color .15s,background-color .15s; }
.canvas [data-drill] { border-color:#a4b69b; }
.canvas [data-drill]::after { content:'↗'; position:absolute; right:5px; top:1px; color:#819576; font:14px/1 Arial,sans-serif; }
.canvas .connection { cursor:pointer; }
.canvas .edge { pointer-events:auto; }
.canvas .edge::before { content:''; position:absolute; inset:-8px 0; }
.canvas .is-active:not(.connection) { outline:2px solid #6f885f; outline-offset:3px; }
.canvas .connection.is-active .edge { border-top-color:#536f42; border-top-width:2.6px; }
.canvas .connection.is-active .edge.arrow::after { border-left-color:#536f42; }
.canvas .connection.is-active .wire { border-color:#536f42!important; }
.canvas .connection.is-active .tip { border-color:#536f42!important; }
.canvas .connection.is-active>g>path { stroke:#536f42!important; stroke-width:2px!important; }
.vector-canvas svg { display:block; max-width:none; overflow:visible; }
.vector-canvas [data-map-node].is-active { outline-offset:5px; }
.tm-flowing .connection { animation:tm-emphasis 2.4s ease-in-out infinite; }
@keyframes tm-emphasis { 50% { opacity:.35; } }
.canvas .is-muted { opacity:.24; }
.canvas .is-visited.event { border-left:3px solid #a7b49a; }
.canvas .is-visited.failed { border-left-color:#c3955e; }
.tm-replaying .connection.is-active .edge { border-top:0; height:2.5px; background:repeating-linear-gradient(90deg,#536f42 0 8px,transparent 8px 13px); animation:tm-flow .8s linear infinite; }
@keyframes tm-flow { to { background-position:26px 0; } }
.tm-aside { flex:0 0 280px; width:280px; max-height:720px; overflow-y:auto; padding:18px; border-left:1px solid #e2e5e8; background:#fff; }
.tm-aside[hidden] { display:none; }
.tm-aside h3 { margin:0 0 12px; font-size:16px; font-weight:500; line-height:1.5; }
.tm-aside h3:not(:first-child) { margin-top:24px; }
.tm-aside p { margin:8px 0 18px; font-size:13px; line-height:1.7; }
.tm-aside .tm-node-detail { font-size:14px; white-space:pre-line; overflow-wrap:anywhere; }
.tm-aside dl { margin:14px 0; }
.tm-aside dt { color:#71767e; font-size:12px; margin:12px 0 3px; }
.tm-aside dd { margin:0; font-size:14px; line-height:1.65; overflow-wrap:anywhere; }
.tm-aside button { display:block; width:100%; text-align:left; margin-top:8px; }
.tm-related { padding:10px; }
.tm-aside small { color:#71767e; }
.tm-status { padding:10px 14px; border-top:1px solid #e2e5e8; color:#71767e; font-size:12px; }
.tm-replay { padding:10px 14px; border-bottom:1px solid #e2e5e8; }
.tm-replay input { min-width:100px; flex:1; accent-color:#73876b; }
.tm-replay output { font-variant-numeric:tabular-nums; white-space:nowrap; color:#64705e; }
.tm-case .tm-viewport { overflow:auto; scrollbar-gutter:stable; touch-action:pan-x pan-y pinch-zoom; }
.tm-case .tm-world { position:relative; }
.tm-case .tm-world>.diagram-root { position:absolute; transform-origin:0 0; }
.tm-case .canvas .is-muted { opacity:1; }
.tm-navigator { flex:0 0 120px; width:120px; padding:14px 11px; border-right:1px solid #e2e5e8; background:#fff; }
.tm-navigator-title { display:block; font-size:12px; margin-bottom:10px; }
.tm-navigator small { display:block; color:#71767e; font-size:11px; margin-top:10px; }
.tm-minimap { display:block; position:relative; width:96px; padding:0; border:0; border-radius:0; overflow:hidden; background:#fcfdfb; }
.tm-minimap .tm-mini-canvas { position:absolute; left:0; top:0; transform-origin:0 0; pointer-events:none; }
.tm-minimap-frame { position:absolute; border:1.5px solid #69815e; background:#69815e18; pointer-events:none; }
:host([data-expanded]) .tm-shell { height:100%; display:flex; flex-direction:column; border:0; border-radius:0; }
:host([data-expanded]) .tm-body { flex:1; min-height:0; }
:host([data-expanded]) .tm-viewport { height:100% !important; touch-action:none; }
:host([data-expanded]) .tm-case .tm-viewport { touch-action:pan-x pan-y pinch-zoom; }
:host([data-expanded]) .tm-aside { max-height:100%; }
@media(max-width:700px) {
  .tm-toolbar { padding:10px; }
  .tm-tools { gap:4px; }
  button,select { font-size:12px; padding:7px 8px; }
  .tm-body { flex-direction:column; }
  .tm-viewport { flex:none; width:100%; }
  .tm-aside { width:100%; max-height:260px; flex:none; border-left:0; border-top:1px solid #e2e5e8; }
  :host([data-expanded]) .tm-viewport { flex:1; min-height:160px; }
  :host([data-expanded]) .tm-aside { max-height:210px; }
  .tm-case .tm-body { flex-direction:row; flex-wrap:wrap; }
  .tm-case .tm-navigator { flex-basis:64px; width:64px; padding:10px 6px; }
  .tm-case .tm-navigator small { display:none; }
  .tm-case .tm-minimap { transform:scale(.52); transform-origin:top left; margin-right:-46px; margin-bottom:-118px; }
  .tm-case .tm-viewport { flex:1; width:auto; }
  .tm-case .tm-aside { flex-basis:100%; }
  :host([data-expanded]) .tm-case .tm-body { display:grid; grid-template-columns:64px minmax(0,1fr); grid-template-rows:minmax(160px,1fr) auto; }
  :host([data-expanded]) .tm-case .tm-aside { grid-column:1 / -1; }
  :host([data-expanded]) .tm-case .tm-viewport { width:100%; }
}
@media(prefers-reduced-motion:reduce) { .canvas [role="button"] { transition:none; } .tm-replaying .connection.is-active .edge,.tm-flowing .connection { animation:none; } }

[data-diagram-style="openai-blog"] {
  --diagram-ink:#202020;
  --diagram-muted:#62625e;
  --diagram-line:#30332e;
  --diagram-border:#3d403a;
  --diagram-accent:#699c35;
  --diagram-accent-ink:#4e7425;
  --diagram-failure:#a07040;
  --diagram-paper:#fff;
  --diagram-soft:#f5faef;
  --diagram-warm:#fcf5e9;
  --diagram-grid:none;
  --diagram-vector-stroke:1.3px;
  --diagram-edge-width:1.8px;
  --diagram-box-width:1.4px;
}
[data-diagram-style="engineering"] {
  --diagram-ink:#252525;
  --diagram-muted:#626262;
  --diagram-line:#454545;
  --diagram-border:#555;
  --diagram-accent:#52634a;
  --diagram-accent-ink:#52634a;
  --diagram-failure:#80604a;
  --diagram-paper:#fff;
  --diagram-soft:#fff;
  --diagram-warm:#fff;
  --diagram-grid:none;
  --diagram-vector-stroke:1.2px;
  --diagram-edge-width:1.6px;
  --diagram-box-width:1.4px;
}
[data-diagram-style] .tm-viewport,[data-diagram-style] .am-viewport {
  background-color:var(--diagram-paper);
  background-image:var(--diagram-grid);
  background-size:20px 20px;
}
[data-diagram-style] .canvas { color:var(--diagram-ink); background-color:var(--diagram-paper); }
[data-diagram-style] .canvas :is(.node,.event,.checkpoint,.restore,.bundle) {
  border-color:var(--diagram-border)!important;
  color:var(--diagram-ink);
}
[data-diagram-kind="flow"] :is(.node,.event,.checkpoint,.restore,.bundle) { border-width:var(--diagram-box-width); }
[data-diagram-style] .canvas :is(.sub,.note,.edge-label,.label:not(.title),.key,.index,.legend) { color:var(--diagram-muted); }
[data-diagram-style] .canvas :is(.node.soft,.node.accent,.node.output,.node.result,.event.repaired) { background-color:var(--diagram-soft)!important; border-color:var(--diagram-accent)!important; }
[data-diagram-style] .canvas :is(.node.failed,.node.issue,.event.failed) { background-color:var(--diagram-warm)!important; border-color:var(--diagram-failure)!important; }
[data-diagram-style] .canvas .edge { border-top-color:var(--diagram-line)!important; border-top-width:var(--diagram-edge-width); }
[data-diagram-style] .canvas .edge.arrow::after { border-left-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .edge:is(.feedback,.rewind,.retry,.handoff) { border-top-color:var(--diagram-accent)!important; }
[data-diagram-style] .canvas .edge:is(.feedback,.rewind,.retry,.handoff).arrow::after { border-left-color:var(--diagram-accent)!important; }
[data-diagram-style] .canvas .edge:is(.failure,.attempt) { border-top-color:var(--diagram-failure)!important; }
[data-diagram-style] .canvas .edge:is(.failure,.attempt).arrow::after { border-left-color:var(--diagram-failure)!important; }
[data-diagram-style] .canvas .wire { border-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .tip { border-top-color:var(--diagram-line)!important; border-right-color:var(--diagram-line)!important; }
[data-diagram-style] [data-diagram-stroke="neutral"] { stroke:var(--diagram-line)!important; stroke-width:var(--diagram-vector-stroke)!important; }
[data-diagram-style] [data-diagram-stroke="guide"] { stroke:#e3e5df!important; }
[data-diagram-style] [data-diagram-stroke="accent"] { stroke:var(--diagram-accent)!important; stroke-width:var(--diagram-vector-stroke)!important; }
[data-diagram-style] [data-diagram-fill="paper"] { fill:var(--diagram-paper)!important; }
[data-diagram-style] [data-diagram-fill="node"] { fill:#fff!important; }
[data-diagram-style] [data-diagram-fill="soft"],
[data-diagram-style] [data-diagram-fill="accent"] { fill:var(--diagram-soft)!important; }
[data-diagram-style="openai-blog"][data-diagram-kind="flow"] [data-diagram-fill="soft"] { fill:url(#writing-dot-neutral)!important; }
[data-diagram-style="openai-blog"][data-diagram-kind="flow"] [data-diagram-fill="accent"] { fill:url(#writing-dot-accent)!important; }
[data-diagram-style="openai-blog"] rect[data-diagram-node] { rx:7.2px; }
[data-diagram-style="engineering"] rect[data-diagram-node] { rx:2px; }
[data-diagram-style] [data-diagram-text="primary"] { fill:var(--diagram-ink)!important; }
[data-diagram-style] [data-diagram-text="secondary"] { fill:var(--diagram-muted)!important; }
[data-diagram-style] [data-diagram-text="accent"] { fill:var(--diagram-accent-ink)!important; }
[data-diagram-style] .canvas .connection.is-active .edge { border-top-color:var(--diagram-accent)!important; border-top-width:2.6px; }
[data-diagram-style] .canvas .connection.is-active .edge.arrow::after { border-left-color:var(--diagram-accent)!important; }
[data-diagram-style] .canvas.tm-replaying .connection.is-active .edge { border-top-width:0; }
[data-diagram-style] .canvas .connection.is-active [data-diagram-stroke] { stroke:var(--diagram-accent)!important; stroke-width:2px!important; }
[data-diagram-style] .automation-map,.automation-map[data-diagram-style] { --map-border:var(--diagram-border); --map-accent:var(--diagram-accent); --map-soft:var(--diagram-soft); }
[data-diagram-style] .am-edge { stroke:var(--diagram-line); stroke-width:var(--diagram-edge-width); }
[data-diagram-style] marker path { stroke:var(--diagram-line); }
[data-diagram-style] .am-node { border-color:var(--diagram-border); border-width:var(--diagram-box-width); border-radius:8px; box-shadow:none; color:var(--diagram-ink); }
[data-diagram-style] .am-node-note,[data-diagram-style] .am-label { color:var(--diagram-muted); }
[data-diagram-style] .am-label { background:var(--diagram-paper); }
[data-diagram-style] .am-edge.is-active { stroke:var(--diagram-accent); stroke-width:2.6px; }
[data-diagram-style] .canvas :is(.arrow:not(.edge),.rule) { border-top-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .arrow:not(.edge)::after { border-left-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .vertical { border-left-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .down::after { border-top-color:var(--diagram-line)!important; }
[data-diagram-style] .canvas .up::after { border-bottom-color:var(--diagram-line)!important; }
[data-diagram-style="openai-blog"].tm-shell,
[data-diagram-style="openai-blog"].automation-map { border:1px solid transparent; border-radius:0; box-shadow:none; }
[data-diagram-style="openai-blog"] :is(.tm-toolbar,.am-toolbar) { border-bottom:1px solid #e4e8e0; padding:14px; background:#fff; }
[data-diagram-style="openai-blog"] :is(.tm-toolbar,.am-toolbar) :is(button,select) { border-color:transparent; border-radius:0; background:transparent; }
[data-diagram-style="openai-blog"] :is(.tm-toolbar,.am-toolbar) button:hover { background:#f2f5ec; }
