*{box-sizing:border-box}
.canvas{position:relative;width:1200px;height:1460px;overflow:hidden;background:white;color:#20231f;font:26px/1.5 -apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',Arial,sans-serif}
.node{position:absolute;z-index:2;border:1.4px solid #454a40;border-radius:9px;background:white;padding:12px 14px;display:flex;flex-direction:column;justify-content:center;text-align:center}
.node .action{font-size:28px;line-height:1.3;font-weight:400}
.node .sub{font-size:23px;line-height:1.45;color:#686c62;margin-top:7px}
.node.token{padding:8px 3px;border-radius:7px}
.node.observation{border:1px dashed #b5bcae;background:#fafbf7;color:#7c8476}
.node.soft{background-color:#f7faef;border-color:#82a65b;background-image:radial-gradient(#79a4433d .6px,transparent .75px);background-size:6px 6px}
.node.reward{border-color:#83a461;background:#f7faef;padding:8px 4px}
.node.reward .action{font-size:27px;white-space:nowrap}
.node sub{font-size:65%;line-height:0}
#G-input-observation .action{line-height:1.6}
[data-node-detail]{display:none}
.label{position:absolute;z-index:3;font-size:22px;line-height:1.5;color:#646b5e;background:white;padding:0 6px}
.label.heading{font-size:32px;color:#20231f;padding:0}
.label.section{font-size:27px;color:#30372a;padding:0}
.label.row{font-size:27px;color:#20231f;padding:0}
.label.row span{display:block;font-size:22px;color:#72796a;line-height:1.5;margin-top:5px}
.label.weight{font-size:23px;color:#6c7562}
.label.hop{font:24px/1.2 Georgia,serif;color:#363e2e;padding:0 7px}
.edge{position:absolute;height:0;border-top:1.6px solid #444b3b;transform-origin:left center;z-index:1}
.edge.arrow:after{content:'';position:absolute;right:-1px;top:-5px;border-left:8px solid #444b3b;border-top:4px solid transparent;border-bottom:4px solid transparent}
.edge.soft{border-top-color:#82a65b}.edge.soft.arrow:after{border-left-color:#82a65b}
.edge.context{border-top-style:dashed;border-top-color:#8c9980}.edge.context.arrow:after{border-left-color:#8c9980}
.rule{position:absolute;height:0;border-top:1px solid #dce0d6}
.value-card{padding:16px 0 0;justify-content:flex-start;border-color:#c9d2be;border-radius:8px}
.value-card .action{font-size:25px}
.value-card .matrix{margin-top:10px;display:grid;grid-template-columns:1fr 1fr;grid-auto-rows:53px;font-size:27px;line-height:53px}
.value-card .matrix .token-name{font:27px/53px Georgia,serif;color:#747c6a}
.value-card .matrix .target{background:#f2f7e8;color:#4b652f}
.value-card .matrix .advantage{color:#263a16}
